import{_ as E,C as l,o as a,c as i,a3 as e,b as r,w as n,a as o,E as s,a4 as A}from"./chunks/framework.CWYzGJW1.js";const M=JSON.parse('{"title":"E4 每週報告自動化","description":"每週報告是規則固定的流程, 適合交給 n8n (流程自動化平台) 排程執行, 不需要代理自己決定步驟.","frontmatter":{"description":"每週報告是規則固定的流程, 適合交給 n8n (流程自動化平台) 排程執行, 不需要代理自己決定步驟."},"headers":[],"relativePath":"examples/e4-weekly-report.md","filePath":"examples/e4-weekly-report.md","lastUpdated":1793060541000}'),B={name:"examples/e4-weekly-report.md"};function h(p,t,c,C,b,u){const d=l("Mermaid");return a(),i("div",null,[t[1]||(t[1]=e('<h1 id="e4-每週報告自動化" tabindex="-1">E4 每週報告自動化 <a class="header-anchor" href="#e4-每週報告自動化" aria-label="Permalink to &quot;E4 每週報告自動化&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-27</li><li>待查證: n8n 與 LiteLLM 設定依官方文件整理, 未實機驗證; n8n 的 OpenAI 憑證是否可改指向 OpenAI 相容 API, 官方憑證文件未說明, 因此本頁改用 HTTP Request 節點; 工具名稱 (ticket.list_closed 等) 為示意; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 每週報告是規則固定的流程, 適合交給 n8n (流程自動化平台) 排程執行, 不需要代理自己決定步驟. n8n 經 MCP gateway (所有工具呼叫的單一出入口) 呼叫唯讀工具取得工作紀錄與指標, 由程式計算數字, 再經 LiteLLM (模型閘道) 請模型撰寫文字說明; 草稿送給負責人確認, 確認後才寄出. 對外發信屬 A3 (不可回復), 一律人工核准, 而且郵件工具寄出前會再查一次核准紀錄, 不只靠 n8n 流程本身.</p><p><strong>對象</strong>: 企業. <strong>需要的模組</strong>: M0 至 M6, M9 (另需 M7 的工具閘道; 不需要程式碼沙箱).</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>n8n</td><td>以拖拉方塊組出自動化流程的工具; 每個方塊稱為節點 (node), 負責一個步驟</td></tr><tr><td>排程 (schedule) 與 cron</td><td>排程讓流程在固定時間自動執行; cron 是描述「每週幾, 幾點」的寫法</td></tr><tr><td>Webhook</td><td>一個專用網址, 有人呼叫這個網址時, 流程就收到通知並繼續往下走</td></tr><tr><td>MCP gateway</td><td>所有工具呼叫的單一出入口, 決定哪個程式能用哪些工具 (見 <a href="/lanai-handbook/build/m7-tools-sandbox">M7</a>)</td></tr><tr><td>虛擬金鑰</td><td>模型閘道 LiteLLM 發給每個程式的通行證, 可以限定能用的模型與用量</td></tr><tr><td>權杖 (token)</td><td>程式向其他系統證明身分用的一串字元, 作用類似通行證</td></tr><tr><td>Bearer, Basic Auth, JWT</td><td>三種在請求中證明身分的方式: Bearer 是在標頭附上一串權杖; Basic Auth 是附上帳號與密碼; JWT 是由簽發者簽章, 內含身分資訊的權杖</td></tr><tr><td>Streamable HTTP</td><td>MCP 規格定義的一種連線方式, 讓客戶端經一般的 HTTP 連線呼叫遠端的 MCP 伺服器</td></tr><tr><td>雜湊值 (hash)</td><td>由檔案內容算出的一串固定長度字元; 內容只要改一個字, 雜湊值就會不同, 可以用來確認核准的就是這份草稿</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="情境" tabindex="-1">情境 <a class="header-anchor" href="#情境" aria-label="Permalink to &quot;情境&quot;">​</a></h2><p>一個 IT 維運團隊每週五要交週報給主管, 每月另交一份服務報告給外部客戶. 內容大致固定: 本週結案工單數, 尚未結案的重大事件, 系統可用率, 下週計畫. 承辦人每次要登入工單系統, 監控平台與工作紀錄表, 手動複製數字, 再寫成文字, 每次約需半天, 而且偶爾抄錯數字.</p><p>本範例把「收集數字」與「寫成文字」交給自動流程, 承辦人只負責檢查草稿與按下核准. 治理設計要回答三個問題: 數字對不對, 寄給誰, 以及誰同意寄出.</p><p>這條流程可以想成一條固定的報表生產線: 會計先把數字算好填進表格, 文書人員只負責寫文字說明, 不能改表格; 主管看過簽核後, 才交給收發室寄出, 而收件名單由收發室保管, 文書人員改不了.</p><h2 id="需要的模組" tabindex="-1">需要的模組 <a class="header-anchor" href="#需要的模組" aria-label="Permalink to &quot;需要的模組&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>里程碑</th><th>在本範例的用途</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/build/m0-foundation">M0 基礎環境</a></td><td>里程碑 1</td><td>自動化區, 閘道區, 工具區, 推論區, 稽核區 VM</td></tr><tr><td><a href="/lanai-handbook/build/m1-inference">M1 推論伺服器</a></td><td>里程碑 1</td><td>vLLM 執行撰寫草稿的對話模型</td></tr><tr><td><a href="/lanai-handbook/build/m2-ui-proxy">M2 使用者介面與反向代理</a></td><td>里程碑 1</td><td>n8n 的核准網址經反向代理提供; 反向代理只轉送 n8n 的 Webhook 路徑, 只限內網</td></tr><tr><td><a href="/lanai-handbook/build/m3-model-intake">M3 模型入庫與存放</a></td><td>里程碑 2</td><td>模型經入庫檢查</td></tr><tr><td><a href="/lanai-handbook/build/m4-retrieval">M4 檢索 (RAG)</a></td><td>里程碑 2</td><td>可選: 參考過去的週報格式</td></tr><tr><td><a href="/lanai-handbook/build/m5-gateway-identity">M5 模型閘道與身分驗證</a></td><td>里程碑 2</td><td>n8n 專用的 LiteLLM 虛擬金鑰, 限制可用模型與用量</td></tr><tr><td><a href="/lanai-handbook/build/m6-observability">M6 可觀測, 稽核與評估</a></td><td>里程碑 2</td><td>每次執行與每次工具呼叫的紀錄; 歷史週報當測試資料</td></tr><tr><td><a href="/lanai-handbook/build/m7-tools-sandbox">M7 工具與沙箱</a> (只用 MCP gateway)</td><td>里程碑 3</td><td>工單, 監控, 郵件的 MCP 伺服器都經工具閘道呼叫</td></tr><tr><td><a href="/lanai-handbook/build/m9-automation">M9 流程自動化</a></td><td>里程碑 3</td><td>n8n 排程, 彙整, 等待核准</td></tr></tbody></table><p>M9 的前置模組包含 M7: n8n 依本手冊的架構只經 LiteLLM 與 MCP gateway 對外, 本身不保存外部系統的金鑰.</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><p>n8n 每週五下午自動啟動, 經工具閘道從工單, 監控與工作紀錄系統取得資料; 程式先算好數字, 模型只寫文字說明, 程式再確認草稿裡的數字都來自計算結果. 草稿連同核准網址送給負責人, 流程停下來等待; 負責人核准後才寄出, 拒絕或逾時就不寄. 下圖的編號對應這七個步驟.</p>',14)),(a(),r(A,null,{default:n(()=>[s(d,{id:"mermaid-264",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%87%AA%E5%8B%95%E5%8C%96%E5%8D%80%3A%20n8n%22%5D%20--%3E%7C%221.%20Schedule%20Trigger%3A%20%E6%AF%8F%E9%80%B1%E4%BA%94%2014%3A00%20(%E5%B7%A5%E4%BD%9C%E6%B5%81%E7%A8%8B%E6%99%82%E5%8D%80%E8%A8%AD%E7%82%BA%20Asia%2FTaipei)%22%7C%20B%5B%22MCP%20Client%20%E7%AF%80%E9%BB%9E%22%5D%0A%20%20B%20--%3E%7C%22Streamable%20HTTP%2C%20%E4%BE%9D%E9%96%98%E9%81%93%E7%9A%84%E9%A9%97%E8%AD%89%E6%96%B9%E5%BC%8F%22%7C%20G1%5B%22%E9%96%98%E9%81%93%E5%8D%80%3A%20MCP%20gateway%22%5D%0A%20%20G1%20--%3E%20T1%5B%22%E5%B7%A5%E5%85%B7%E5%8D%80%3A%20%E5%B7%A5%E5%96%AE%20MCP%20%E4%BC%BA%E6%9C%8D%E5%99%A8%3Cbr%2F%3Eticket.list_closed%20(A0)%22%5D%0A%20%20G1%20--%3E%20T2%5B%22%E5%B7%A5%E5%85%B7%E5%8D%80%3A%20%E7%9B%A3%E6%8E%A7%20MCP%20%E4%BC%BA%E6%9C%8D%E5%99%A8%3Cbr%2F%3Emetrics.availability%20(A0)%22%5D%0A%20%20G1%20--%3E%20T3%5B%22%E5%B7%A5%E5%85%B7%E5%8D%80%3A%20%E5%B7%A5%E4%BD%9C%E7%B4%80%E9%8C%84%20MCP%20%E4%BC%BA%E6%9C%8D%E5%99%A8%3Cbr%2F%3Eworklog.list%20(A0)%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%A8%8B%E5%BC%8F%E7%AF%80%E9%BB%9E%3Cbr%2F%3E2.%20%E8%A8%88%E7%AE%97%E6%95%B8%E5%AD%97%2C%20%E5%A1%AB%E5%85%A5%E9%80%B1%E5%A0%B1%E7%9A%84%E5%9B%BA%E5%AE%9A%E8%A1%A8%E6%A0%BC%20(%E6%A8%A1%E5%9E%8B%E4%B8%8D%E7%B6%93%E6%89%8B%E6%95%B8%E5%AD%97)%22%5D%0A%20%20C%20--%3E%20D%5B%22HTTP%20Request%20%E7%AF%80%E9%BB%9E%22%5D%0A%20%20D%20--%3E%7C%22POST%20%2Fchat%2Fcompletions%2C%20%E8%99%9B%E6%93%AC%E9%87%91%E9%91%B0%22%7C%20L%5B%22%E9%96%98%E9%81%93%E5%8D%80%3A%20LiteLLM%22%5D%0A%20%20L%20--%3E%20V%5B%22%E6%8E%A8%E8%AB%96%E5%8D%80%3A%20vLLM%22%5D%0A%20%20D%20--%3E%7C%223.%20%E6%A8%A1%E5%9E%8B%E5%8F%AA%E6%92%B0%E5%AF%AB%E6%96%87%E5%AD%97%E8%AA%AA%E6%98%8E%22%7C%20E%5B%22%E7%A8%8B%E5%BC%8F%E7%AF%80%E9%BB%9E%3Cbr%2F%3E4.%20%E6%AA%A2%E6%9F%A5%E8%8D%89%E7%A8%BF%E4%B8%AD%E7%9A%84%E6%95%B8%E5%AD%97%E9%83%BD%E4%BE%86%E8%87%AA%E7%AC%AC%202%20%E6%AD%A5%E7%9A%84%E8%A8%88%E7%AE%97%E7%B5%90%E6%9E%9C%22%5D%0A%20%20E%20--%3E%20F%5B%22MCP%20Client%20%E7%AF%80%E9%BB%9E%3Cbr%2F%3E5.%20%E6%8A%8A%E8%8D%89%E7%A8%BF%E8%88%87%E6%A0%B8%E5%87%86%E7%B6%B2%E5%9D%80%20(%24execution.resumeUrl)%20%E9%80%81%E7%B5%A6%E8%B2%A0%E8%B2%AC%E4%BA%BA%22%5D%0A%20%20F%20--%3E%20G2%5B%22MCP%20gateway%22%5D%0A%20%20G2%20--%3E%20N1%5B%22%E5%85%A7%E9%83%A8%E9%80%9A%E8%A8%8A%E6%88%96%E5%B7%A5%E5%96%AE%E5%B7%A5%E5%85%B7%20(A1%2C%20%E5%85%A7%E9%83%A8%E5%8F%AF%E8%A6%8B)%22%5D%0A%20%20F%20--%3E%20W%5B%22Wait%20%E7%AF%80%E9%BB%9E%3Cbr%2F%3E6.%20On%20Webhook%20Call%2C%20%E6%9C%80%E9%95%B7%E7%AD%89%E5%88%B0%E7%95%B6%E5%A4%A9%E4%B8%8B%E7%8F%AD%E5%89%8D%22%5D%0A%20%20W%20--%3E%7C%22%E9%80%BE%E6%99%82%E6%88%96%E6%8B%92%E7%B5%95%22%7C%20X%5B%22%E4%B8%8D%E5%AF%84%E5%87%BA%2C%20%E9%80%9A%E7%9F%A5%E8%B2%A0%E8%B2%AC%E4%BA%BA%2C%20%E6%B5%81%E7%A8%8B%E7%B5%90%E6%9D%9F%22%5D%0A%20%20W%20--%3E%7C%22%E8%B2%A0%E8%B2%AC%E4%BA%BA%E6%A0%B8%E5%87%86%20(%E7%B6%93%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%E5%91%BC%E5%8F%AB%E6%A0%B8%E5%87%86%E7%B6%B2%E5%9D%80%2C%20%E9%9C%80%E9%A9%97%E8%AD%89)%22%7C%20M%5B%22MCP%20Client%20%E7%AF%80%E9%BB%9E%3Cbr%2F%3E7.%20mail.send%20(A3)%22%5D%0A%20%20M%20--%3E%20G3%5B%22MCP%20gateway%22%5D%0A%20%20G3%20--%3E%20MS%5B%22%E9%83%B5%E4%BB%B6%20MCP%20%E4%BC%BA%E6%9C%8D%E5%99%A8%3A%20%E5%85%88%E6%9F%A5%E7%A8%BD%E6%A0%B8%E5%8D%80%E6%9C%89%E7%84%A1%E5%B0%8D%E6%87%89%E7%9A%84%E6%A0%B8%E5%87%86%E7%B4%80%E9%8C%84%E8%88%87%E8%8D%89%E7%A8%BF%E9%9B%9C%E6%B9%8A%E5%80%BC%2C%20%E6%9C%89%E6%89%8D%E5%AF%84%E5%87%BA%22%5D%0A%20%20MS%20--%3E%20R%5B%22%E6%94%B6%E4%BB%B6%E8%80%85%3A%20%E5%90%8D%E5%96%AE%E5%9B%BA%E5%AE%9A%E5%9C%A8%E9%83%B5%E4%BB%B6%E5%B7%A5%E5%85%B7%E7%9A%84%E8%A8%AD%E5%AE%9A%E4%B8%AD%2C%20%E4%B8%8D%E7%94%B1%E6%A8%A1%E5%9E%8B%E6%B1%BA%E5%AE%9A%22%5D%0A%20%20Z1%5B%22%E7%B4%80%E9%8C%84%3A%20n8n%20%E5%9F%B7%E8%A1%8C%E7%B4%80%E9%8C%84%2C%20MCP%20gateway%20%E8%88%87%20LiteLLM%20%E5%91%BC%E5%8F%AB%E7%B4%80%E9%8C%84%22%5D%20--%3E%20Z2%5B%22%E7%A8%BD%E6%A0%B8%E5%8D%80%22%5D%0A%20%20Z2%20--%3E%20Z3%5B%22%E6%97%A2%E6%9C%89%20SIEM%22%5D%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<h2 id="設定要點" tabindex="-1">設定要點 <a class="header-anchor" href="#設定要點" aria-label="Permalink to &quot;設定要點&quot;">​</a></h2><p>以下依 n8n 與 LiteLLM 官方文件整理, 未實機驗證.</p><h3 id="排程與時區" tabindex="-1">排程與時區 <a class="header-anchor" href="#排程與時區" aria-label="Permalink to &quot;排程與時區&quot;">​</a></h3><ul><li>Schedule Trigger 節點可用 Weeks 設定 (每隔幾週, 星期幾, 幾點幾分), 也可用 cron 運算式, 例如 n8n 文件中的 <code>0 12 * * 1</code> 代表每週一中午. n8n 文件列出的欄位依序為 (秒), 分, 時, 日, 月, 星期 (Sun-Sat), 其中秒可以省略; 本例的週五 14:00 可寫成 <code>0 14 * * 5</code> (來源: n8n 文件 Schedule Trigger).</li><li>n8n 文件說明, 排程依工作流程的時區設定; 沒有設定時用執行個體的時區, 而自架版預設為 America/New York. 因此要在工作流程設定中把時區改為 Asia/Taipei, 否則會在台灣時間的半夜執行.</li><li>官方文件提醒, 使用 Schedule 觸發的工作流程要儲存並發布 (publish) 才會依排程執行.</li></ul><h3 id="取資料-mcp-client-節點" tabindex="-1">取資料: MCP Client 節點 <a class="header-anchor" href="#取資料-mcp-client-節點" aria-label="Permalink to &quot;取資料: MCP Client 節點&quot;">​</a></h3><ul><li>n8n 的 MCP Client 節點設定伺服器傳輸方式與 MCP 端點網址, 支援 Bearer, Header, 多組 Header 與 OAuth2 驗證, 工具清單會自動從 MCP 伺服器取得 (n8n 文件). 端點網址指向 MCP gateway, 使用 n8n 專用的權杖. 驗證方式依所選的閘道而定: 以 LiteLLM 兼任時, 用標頭帶 <code>x-litellm-api-key</code> (見 <a href="/lanai-handbook/build/m9-automation">M9</a> 的 MCP Client 節點設定表); 使用其他閘道時, 依該閘道的文件設定.</li><li>n8n 這把權杖在 MCP gateway 只開放唯讀工具, 第 5 步送核准通知用的內部通訊或工單工具 (A1), 以及 <code>mail.send</code>; 工單系統, 監控平台與郵件伺服器的帳密只存在工具區的 MCP 伺服器, n8n 看不到.</li></ul><h3 id="寫草稿-經-litellm" tabindex="-1">寫草稿: 經 LiteLLM <a class="header-anchor" href="#寫草稿-經-litellm" aria-label="Permalink to &quot;寫草稿: 經 LiteLLM&quot;">​</a></h3><ul><li>用 HTTP Request 節點呼叫 LiteLLM 的 <code>/chat/completions</code>, 以 <code>Authorization: Bearer &lt;n8n 專用虛擬金鑰&gt;</code> 驗證 (LiteLLM 虛擬金鑰文件的呼叫方式). 金鑰以 <code>/key/generate</code> 建立時, 用 <code>models</code> 限定只能使用撰寫週報的模型, 並以 <code>metadata</code> 標明用途.</li><li>這把金鑰存在 n8n 的憑證中. 它是內部閘道的虛擬金鑰, 不是外部系統的金鑰; 外洩時在 LiteLLM 停用即可, 不影響其他應用.</li></ul><p>提示範本 (數字由程式填好, 模型只寫說明):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>以下是本週維運資料, 表格中的數字已由系統計算, 不得修改, 不得自行計算新的數字.</span></span>
<span class="line"><span>請用繁體中文撰寫週報的文字段落:</span></span>
<span class="line"><span>1. 本週重點 (3 至 5 點, 每點一句).</span></span>
<span class="line"><span>2. 未結案重大事件的現況說明, 只根據事件清單中的描述.</span></span>
<span class="line"><span>3. 下週計畫, 只根據工作紀錄中標為「下週」的事項.</span></span>
<span class="line"><span>資料中沒有的內容寫「本週無資料」, 不要推測原因.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>指標表:</span></span>
<span class="line"><span>{{metrics_table}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>事件清單:</span></span>
<span class="line"><span>{{incidents}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工作紀錄:</span></span>
<span class="line"><span>{{worklog}}</span></span></code></pre></div><p>範本中以兩層大括號標示的位置, 由 n8n 的運算式填入前一步的結果.</p><h3 id="數字檢查" tabindex="-1">數字檢查 <a class="header-anchor" href="#數字檢查" aria-label="Permalink to &quot;數字檢查&quot;">​</a></h3><p>草稿回來後, 以程式節點擷取草稿中的所有數字, 逐一確認出現在第 2 步的計算結果中; 有任何不在清單中的數字, 草稿標記為「需檢查」並在通知中註明 (推論, 信心: 中). 這一步不能證明文字說明正確, 但能擋下模型自行算出或編出的數字.</p><h3 id="人工核准與寄出" tabindex="-1">人工核准與寄出 <a class="header-anchor" href="#人工核准與寄出" aria-label="Permalink to &quot;人工核准與寄出&quot;">​</a></h3><ul><li>n8n 的 Wait 節點支援四種恢復方式: 經過一段時間, 指定時間, 收到 Webhook 呼叫, 表單送出. 本範例用「On Webhook Call」. 每次執行都會產生唯一的恢復網址 <code>$execution.resumeUrl</code>, 可放進通知中; 恢復網址可以要求 Basic Auth, Header Auth 或 JWT 驗證 (n8n 文件). 設定驗證, 不使用 None.</li><li>開啟「Limit Wait Time」, 上限設在當天下班前, 讓週報仍能在週五交出. 官方文件說明, 逾時後流程會自動恢復, 因此逾時後的分支必須是「不寄出, 通知負責人」, 不能直接接寄信節點; 逾時後由承辦人檢查草稿, 手動寄出.</li><li>寄信屬 A3. 核准狀態不只存在 n8n: 負責人核准時, 核准紀錄 (核准者, 時間, 草稿雜湊值) 同時寫入稽核區. 查核准紀錄不是 MCP gateway 本身的功能: M7.2 節的工具閘道依身分與工具名稱授權, 不會去查外部紀錄. 因此這項檢查寫在郵件 MCP 伺服器裡 (或放在它前面的一個自建檢查元件): 收到 <code>mail.send</code> 時, 先以草稿雜湊值查稽核區有無對應的核准紀錄, 沒有就拒絕. 這樣即使 n8n 流程遭竄改, 也無法未經核准寄信 (推論, 信心: 中).</li><li>收件者名單固定在郵件 MCP 伺服器的設定 (例如內部主管群組, 客戶的指定窗口), <code>mail.send</code> 不接受模型或 n8n 傳入的任意收件者.</li></ul><h2 id="驗收方式" tabindex="-1">驗收方式 <a class="header-anchor" href="#驗收方式" aria-label="Permalink to &quot;驗收方式&quot;">​</a></h2><p><strong>1. 歷史資料重跑.</strong> 以過去 4 週的資料執行流程 (不寄出), 和當時人工寫的週報比較:</p><ul><li>指標表的數字與人工版完全一致 (由程式計算, 應為 100%).</li><li>文字說明沒有出現資料中沒有的事件或原因; 由承辦人逐週評分是否可直接使用, 或需修改幾處.</li></ul><p><strong>2. 核准路徑測試.</strong></p><table tabindex="0"><thead><tr><th>測試</th><th>預期結果</th></tr></thead><tbody><tr><td>負責人核准</td><td>寄出一封信, 收件者與設定名單一致</td></tr><tr><td>負責人拒絕</td><td>不寄出, 執行紀錄標為拒絕</td></tr><tr><td>等待逾時</td><td>不寄出, 負責人收到逾時通知</td></tr><tr><td>不帶驗證資訊呼叫恢復網址</td><td>n8n 拒絕, 流程維持等待</td></tr><tr><td>在 n8n 直接呼叫 <code>mail.send</code> (跳過核准)</td><td>郵件 MCP 伺服器查無核准紀錄而拒絕, 留下紀錄 (推論)</td></tr></tbody></table><p><strong>3. 網路邊界.</strong> 依 M9.4 節的要點, 從 n8n 的 VM 直接連工單系統, 監控平台與郵件伺服器都應失敗, 只能經閘道區.</p><p><strong>4. 用量與時區.</strong> 虛擬金鑰超過設定用量時, LiteLLM 拒絕請求, n8n 收到錯誤並通知負責人; 排程實際在台灣時間週五 14:00 觸發.</p><h2 id="風險與限制" tabindex="-1">風險與限制 <a class="header-anchor" href="#風險與限制" aria-label="Permalink to &quot;風險與限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>風險</th><th>影響</th><th>因應方式</th></tr></thead><tbody><tr><td>數字錯誤</td><td>主管或客戶依錯誤的指標做決定</td><td>數字由程式計算並固定在表格; 程式檢查草稿中的數字</td></tr><tr><td>模型捏造事件或原因</td><td>週報內容與事實不符</td><td>提示範本限定只根據資料; 負責人核准前逐段閱讀</td></tr><tr><td>寄錯對象</td><td>內部資訊外流給客戶或無關人員</td><td>收件者名單固定在郵件工具設定; 對外發信一律人工核准</td></tr><tr><td>核准流於形式</td><td>負責人沒看就按核准</td><td>通知中列出「需檢查」的標記與本週與上週的差異; 定期抽查已寄出的週報</td></tr><tr><td>n8n 平台漏洞</td><td>2026 年已有實際利用紀錄的漏洞 (見 M9.1 節)</td><td>獨立 VM, 只能連閘道區; 鎖定版本並追蹤公告; n8n 不保存外部系統金鑰</td></tr><tr><td>恢復網址外洩</td><td>他人可能代為核准</td><td>恢復網址要求驗證; 核准網址只限內網經反向代理存取</td></tr><tr><td>報告含人員績效資訊</td><td>工作紀錄可能涉及個人表現</td><td>週報只呈現團隊層級的彙總; 執行紀錄設定保存期限</td></tr><tr><td>授權</td><td>n8n 採 Sustainable Use License, 非 OSI 開源 (見 M9.1 節)</td><td>依授權只做內部使用; 對外提供服務前先確認授權條款</td></tr></tbody></table><p>需要人工確認的步驟: 每一份草稿寄出前的核准; 所有對外發信.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.scheduletrigger/" target="_blank" rel="noreferrer">n8n 文件: Schedule Trigger node</a></li><li><a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.wait/" target="_blank" rel="noreferrer">n8n 文件: Wait node</a></li><li><a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-langchain.mcpclient/" target="_blank" rel="noreferrer">n8n 文件: MCP Client node</a></li><li><a href="https://docs.n8n.io/integrations/builtin/credentials/openai/" target="_blank" rel="noreferrer">n8n 文件: OpenAI credentials</a></li><li><a href="https://docs.litellm.ai/docs/proxy/virtual_keys" target="_blank" rel="noreferrer">LiteLLM 文件: Virtual Keys</a></li><li>站內: <a href="/lanai-handbook/build/m9-automation">M9 流程自動化</a>, <a href="/lanai-handbook/build/m7-tools-sandbox">M7 工具與沙箱</a>, <a href="/lanai-handbook/examples/e2-alert-triage">E2 資安告警分流</a></li><li>文中的類比 (報表生產線, 收發室): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>`,27))])}const D=E(B,[["render",h]]);export{M as __pageData,D as default};
